<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();if(isset($_GET['id'])){$s=$pdo->prepare("UPDATE contact_messages SET status='Read' WHERE id=?");$s->execute([(int)$_GET['id']]);audit('read','contact_message',(int)$_GET['id']);flash('Message marked as read.');redirect('messages.php');}$rows=$pdo->query('SELECT * FROM contact_messages ORDER BY created_at DESC')->fetchAll();admin_header('Messages','messages.php');?><div class="pagehead"><div><h1>Contact Messages</h1><div class="muted">Public enquiries received through the website.</div></div></div><?php foreach($rows as $r):?><div class="card" style="margin-bottom:12px"><div><strong><?=e($r['name'])?></strong> · <?=e($r['contact'])?> · <span class="badge <?=($r['status']==='New'?'warn':'')?>"><?=e($r['status'])?></span></div><div class="muted"><?=e($r['created_at'])?></div><p><?=nl2br(e($r['message']))?></p><?php if($r['status']==='New'):?><a class="btn secondary" href="?id=<?=$r['id']?>">Mark as read</a><?php endif;?></div><?php endforeach;?><?php admin_footer();
